package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	_ "github.com/shopspring/decimal"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec

var dateFile *os.File
var scanner *bufio.Scanner
var eofReached bool

func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storePIC9(v int64, width int) int64 {
	mod := pow10(width)
	// keep low-order digits, handle negative correctly like COBOL
	// for non-negative it's v % mod
	// for negative, COBOL keeps sign? Not needed here.
	if v >= 0 {
		return v % mod
	}
	// negative: keep low-order digits with sign
	// e.g., -123 with width 2 => -23 ? Simplified.
	av := -v % mod
	if av == 0 {
		return 0
	}
	return -av
}

func parseNumField(s string) int64 {
	if len(s) == 0 {
		return 0
	}
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// If field contains only digits optionally sign, parse.
	// If not, try to extract leading integer
	var neg bool
	if t[0] == '+' || t[0] == '-' {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
		if t == "" {
			return 0
		}
	}
	// ensure all digits
	for _, ch := range t {
		if ch < '0' || ch > '9' {
			return 0
		}
	}
	// parse
	var v int64 = 0
	for _, ch := range t {
		v = v*10 + int64(ch-'0')
	}
	if neg {
		v = -v
	}
	return v
}

func formatPIC9(v int64, width int) string {
	// unedited numeric: zero-padded to digit count, preserving sign if negative
	// values are already stored truncated, so just format
	if v < 0 {
		av := -v
		s := fmt.Sprintf("%0*d", width-1, av)
		// if width is 1, can't fit sign? just format without sign
		if width <= 1 {
			return fmt.Sprintf("%0*d", width, av)
		}
		// COBOL would put sign? but not needed
		return "-" + s
	}
	return fmt.Sprintf("%0*d", width, v)
}

func openDateFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		if os.IsNotExist(err) {
			eofReached = true
			scanner = nil
			dateFile = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	dateFile = f
	scanner = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	eofReached = false
}

func closeDateFile() {
	if dateFile != nil {
		dateFile.Close()
	}
}

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	openDateFile()
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	closeDateFile()
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Println("VALID: " + formatPIC9(WsValid, 2) + " BAD MONTH: " + formatPIC9(WsBadMonth, 2) + " BAD DAY: " + formatPIC9(WsBadDay, 2))
}

func INPUT_DONE() bool {
	return WsEofFlag == "Y"
}

func IS_LEAP() bool {
	return WsLeapFlag == "Y"
}

func READ_PARA() {
	if eofReached {
		WsEofFlag = "Y"
		return
	}
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !scanner.Scan() {
		// check error
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
		eofReached = true
		return
	}
	line := scanner.Text()
	// handle CRLF leftover \r
	if len(line) > 0 && line[len(line)-1] == '\r' {
		line = line[:len(line)-1]
	}
	// LINE SEQUENTIAL: pad with spaces on right if shorter than 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	// parse
	dateRec.DtId = line[0:4]
	dateRec.DtYyyy = parseNumField(line[4:8])
	dateRec.DtMm = parseNumField(line[8:10])
	dateRec.DtDd = parseNumField(line[10:12])
}

func PROCESS_PARA() {
	LEAP_PARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = storePIC9(WsBadMonth+1, 2)
		fmt.Println(dateRec.DtId + " BAD MONTH " + formatPIC9(dateRec.DtMm, 2))
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = storePIC9(WsBadDay+1, 2)
			fmt.Println(dateRec.DtId + " BAD DAY " + formatPIC9(dateRec.DtDd, 2) + " MAX " + formatPIC9(WsMaxDay, 2))
		} else {
			WsValid = storePIC9(WsValid+1, 2)
			fmt.Println(dateRec.DtId + " VALID " + formatPIC9(dateRec.DtYyyy, 4) + "-" + formatPIC9(dateRec.DtMm, 2) + "-" + formatPIC9(dateRec.DtDd, 2))
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	if 4 != 0 {
		WsQ = storePIC9(dateRec.DtYyyy/4, 4)
		WsR4 = storePIC9(dateRec.DtYyyy%4, 3)
	}
	if 100 != 0 {
		WsQ = storePIC9(dateRec.DtYyyy/100, 4)
		WsR100 = storePIC9(dateRec.DtYyyy%100, 3)
	}
	if 400 != 0 {
		WsQ = storePIC9(dateRec.DtYyyy/400, 4)
		WsR400 = storePIC9(dateRec.DtYyyy%400, 3)
	}
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if IS_LEAP() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}
